esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// Gauges. WAL size uses the same aggregation as the "WAL Size" dashboard panel.
// Slot series only exist when a replication slot exists, so a project without one
// returns no rows rather than a false breach.
| STATS
    `Slot Max Lag Bytes` = MAX(LAST_OVER_TIME(replication_slots_max_lag_bytes)),
    `WAL Size (MB)` = MAX(LAST_OVER_TIME(pg_wal_size_mb))
  BY resource.attributes.supabase_project_ref
| EVAL `Slot Max Lag GB` = ROUND(`Slot Max Lag Bytes` / POW(1024, 3), 2)
// 10 GB of retained WAL. Size this against the free space on your data mountpoint —
// on small compute tiers a much lower value is already dangerous.
| WHERE `Slot Max Lag GB` > 10
| SORT `Slot Max Lag GB` DESC
